selectedCompanyId, workflowId, {
        expectedRevisionId: baseRevisionId,
        graph: currentGraph(),
        changeSummary: "Updated in visual builder",
      }

selectedCompanyId, workflowId, {
        expectedDraftRevisionId: baseRevisionId,
        expectedPublishedRevisionId: publishedRevisionId,
        approvalId: null,
      }

issueId!, pauseHoldId, {
            reason: null,
            metadata: {
              wakeAgents,
            },
          }

issueId!, {
        mode,
        reason: null,
        releasePolicy: {
          strategy: "manual",
          ...(mode === "pause"
            ? {
                note: scope === "leaf" ? "leaf_pause" : "full_pause",
              }
            : {}),
        },
        ...(runId
          ? { metadata: { source: "issue_active_run_control", runId } }
          : {}),
